<?php $pay=$page['payment_details'];$sale=$page['sale_record'];$debt=$page['payment_debt'];$balance=$debt['unpaid'];$toCover=$debt['balance'];$collectionCurrency=$debt['currency'];
$fxInvoice=['currency_code'=>$collectionCurrency,'primary_code'=>$sale['currency_primary_code'],'alternate_code'=>$sale['currency_alternate_code'],'exchange_rate'=>$sale['exchange_rate'],'balance'=>$toCover];
if($debt['indexed'])$fxInvoice+=['indexed_native_total'=>$sale['total_amount'],'indexed_usd_total'=>$sale['usd_reference_amount'],'native_balance'=>bcsub(bcsub(bcsub($sale['total_amount'],$pay['credited'],2),$pay['settled'],2),$pay['pending'],2),'native_paid'=>bcadd($pay['settled'],$pay['pending'],2),'usd_paid'=>bcadd($debt['settled'],$debt['pending'],2)]; ?>
<section class="contact-sheet direct-payment" id="registrar-cobro"><h2>Cobros de esta venta</h2>
<div class="direct-metrics"><div><?= bccomp($balance,'0',2)<0?'Saldo a favor del cliente':'Saldo sin confirmar' ?><strong><?= $e((bccomp($balance,'0',2)<0?bcsub('0',$balance,2):$balance).' '.$collectionCurrency) ?></strong></div><div>En revisión<strong><?= $e($debt['pending'].' '.$collectionCurrency) ?></strong></div><div>Por cubrir<strong><?= $e((bccomp($toCover,'0',2)>0?$toCover:'0.00').' '.$collectionCurrency) ?></strong></div></div>
<?php if(isset($_GET['payment_registered'])): ?><p class="notice">Cobro registrado para revisión del jefe. No se confirmó automáticamente.</p><?php endif; ?>
<?php if(permissionHas('venta_directa.sales','register_payment')&&permissionHas('contabilidad.customer_invoices','register_payment')&&$sale['invoice_status']==='posted'&&bccomp($toCover,'0',2)>0): ?>
<details <?= ($_POST['action']??'')==='direct_payment'?'open':'' ?>><summary class="contact-button">Registrar cobro total o parcial</summary>
<form method="post" enctype="multipart/form-data" action="index.php?id=<?= (int)$detail['id'] ?>" class="direct-simple-form" data-direct-payment data-payment-convert-currency data-payment-rate-endpoint="../contabilidad/index.php?type=customer&amp;id=<?= (int)$sale['invoice_id'] ?>" data-payment-pair="<?= $e(json_encode(['primary_code'=>$page['settings']['primary_code'],'alternate_code'=>$page['settings']['alternate_code']])) ?>" data-payment-fx-invoice="<?= $e(json_encode($fxInvoice)) ?>">
<input type="hidden" name="csrf" value="<?= $e($page['csrf']) ?>"><input type="hidden" name="action" value="direct_payment"><input type="hidden" name="request_key" value="<?= $e($page['input']['request_key']??$page['key']) ?>"><input type="hidden" name="version" value="<?= (int)$sale['invoice_version'] ?>">
<label>Importe recibido *<input name="amount" inputmode="decimal" value="<?= $e($page['input']['amount']??$toCover) ?>" required></label>
<label>Moneda<select name="currency_code"><?php foreach(array_unique(array_merge(accountingCurrencyCodes($page['settings']),[$sale['currency_code']])) as $code): ?><option <?= $code===($page['input']['currency_code']??$collectionCurrency)?'selected':'' ?>><?= $e($code) ?></option><?php endforeach; ?></select></label>
<label>Fecha del cobro<input type="date" name="payment_date" value="<?= $e($page['input']['payment_date']??commerceToday()) ?>" max="<?= commerceToday() ?>" required></label>
<label>Cuenta de ingreso *<select name="account_id" required><option value="">Selecciona la caja o banco</option><?php foreach($page['accounts'] as $account): ?><option value="<?= (int)$account['id'] ?>" <?= (int)($page['input']['account_id']??0)===(int)$account['id']?'selected':'' ?>><?= $e($account['name'].' · '.($account['currency_code']?:'Multimoneda')) ?></option><?php endforeach; ?></select></label>
<label>Medio de pago *<select name="method_id" required><option value="">Selecciona el medio</option><?php foreach($page['methods'] as $method): ?><option value="<?= (int)$method['id'] ?>" <?= (int)($page['input']['method_id']??0)===(int)$method['id']?'selected':'' ?>><?= $e($method['name']) ?></option><?php endforeach; ?></select></label>
<label>Referencia<input name="reference" maxlength="160" value="<?= $e($page['input']['reference']??'') ?>"></label>
<label>Comprobante (foto o PDF)<input type="file" name="proof_files[]" accept="image/jpeg,image/png,image/webp,image/gif,application/pdf" multiple></label>
<label>Tasa del cobro<input name="exchange_rate" inputmode="decimal" value="<?= $e($page['input']['exchange_rate']??$page['settings']['exchange_rate']??'') ?>"><small>1 <?= $e($page['settings']['primary_code']) ?> = tasa en <?= $e($page['settings']['alternate_code']) ?>.</small></label>
<p data-payment-rate-status aria-live="polite"></p><p class="notice" data-payment-fx-preview aria-live="polite" hidden></p>
<p>El importe corresponde a la moneda del cobro. La deuda de las facturas vinculadas a USD se cubre con la tasa de la fecha del cobro. Quedará pendiente de validación.</p><button class="contact-button contact-button-primary" type="submit">Registrar cobro</button></form></details>
<?php endif; ?>
<?php if($debt['indexed']): ?><p>La factura conserva <?= $e($sale['total_amount'].' VES') ?> originales y una referencia de <?= $e($sale['usd_reference_amount'].' USD') ?>.</p><?php endif; ?>
<?php foreach($pay['payments'] as $payment): ?><div class="direct-history-row"><span><?= $e($payment['payment_date'].' · '.$payment['reference']) ?><small><?= $e(['pending'=>'En revisión','settled'=>'Confirmado','cancel'=>'Cancelado'][$payment['status']]??$payment['status']) ?></small></span><strong><?= $e(($payment['usd_reference_amount']??$payment['amount']).' '.$collectionCurrency) ?><small><?= $e($payment['payment_amount'].' '.$payment['payment_currency']) ?></small><?php if($payment['fx_difference']!==null): ?><small>Diferencial: <?= $e($payment['fx_difference'].' '.$payment['fx_currency_code']) ?></small><?php endif; ?></strong></div><?php endforeach; ?>
</section>
